// Generates src/ic/blocks.generated.ts and schema/profile.schema.json.
// Run with: npm run gen
import { mkdirSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { profileJsonSchema } from "../src/profile/jsonschema.ts";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");

export function blocksModule(): string {
  const dir = join(root, "src/ic/blocks");
  const files = readdirSync(dir).filter((f) => f.endsWith(".md")).sort();
  const lines = [
    "// Generated by scripts/gen.ts from src/ic/blocks/*.md. Do not edit.",
    "// REQ-IC-009",
    "export const BLOCKS: Record<string, string> = {",
  ];
  for (const f of files) {
    const text = readFileSync(join(dir, f), "utf8");
    lines.push(`  ${JSON.stringify(f.replace(/\.md$/, ""))}: ${JSON.stringify(text)},`);
  }
  lines.push("};", "");
  return lines.join("\n");
}

export function assistPromptModule(): string {
  const text = readFileSync(join(root, "src/elicit/assist/prompt.md"), "utf8");
  return [
    "// Generated by scripts/gen.ts from src/elicit/assist/prompt.md. Do not edit.",
    "// REQ-ELIC-006",
    `export const ASSIST_PROMPT = ${JSON.stringify(text)};`,
    "",
  ].join("\n");
}

export function schemaFile(): string {
  return JSON.stringify(profileJsonSchema(), null, 2) + "\n";
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  writeFileSync(join(root, "src/ic/blocks.generated.ts"), blocksModule());
  writeFileSync(join(root, "src/elicit/assist/prompt.generated.ts"), assistPromptModule());
  mkdirSync(join(root, "schema"), { recursive: true });
  writeFileSync(join(root, "schema/profile.schema.json"), schemaFile());
  console.log("wrote generated modules and schema/profile.schema.json");
}
